package cakenifydb

import (
	"encoding/json"
	"time"

	"github.com/google/uuid"
)

type User struct {
	ID           uuid.UUID
	Username     string
	PasswordHash string
	IsAdmin      bool
	CreatedAt    time.Time
}

// CreateUserParams holds the parameters for creating a new user. ID is
// generated by the caller (core layer), not the DB, matching the rest of
// the domain's ID-ownership convention.
type CreateUserParams struct {
	ID           uuid.UUID `validate:"required"`
	Username     string    `validate:"required"`
	PasswordHash string    `validate:"required"`
	IsAdmin      bool
}

type Session struct {
	ID        uuid.UUID
	UserID    uuid.UUID
	ExpiresAt time.Time
}

type CreateSessionParams struct {
	ID        uuid.UUID `validate:"required"`
	UserID    uuid.UUID `validate:"required"`
	ExpiresAt time.Time `validate:"required"`
}

type Birthday struct {
	ID         uuid.UUID
	UserID     uuid.UUID
	PersonName string
	BirthMonth int
	BirthDay   int
	BirthYear  *int
	Notes      string
	CreatedAt  time.Time
	UpdatedAt  time.Time
}

type CreateBirthdayParams struct {
	ID         uuid.UUID `validate:"required"`
	UserID     uuid.UUID `validate:"required"`
	PersonName string    `validate:"required"`
	BirthMonth int       `validate:"required,min=1,max=12"`
	BirthDay   int       `validate:"required,min=1,max=31"`
	BirthYear  *int
	Notes      string
}

type UpdateBirthdayParams struct {
	PersonName string `validate:"required"`
	BirthMonth int    `validate:"required,min=1,max=12"`
	BirthDay   int    `validate:"required,min=1,max=31"`
	BirthYear  *int
	Notes      string
}

// MonthDay identifies a birthday by month/day only, ignoring year — used to
// match "today" (a single MonthDay) and the weekly digest (up to 7).
type MonthDay struct {
	Month int
	Day   int
}

type NotificationSetting struct {
	ID       uuid.UUID
	UserID   uuid.UUID
	Strategy string
	Config   json.RawMessage
	Enabled  bool
}

type UpsertNotificationSettingParams struct {
	ID       uuid.UUID       `validate:"required"`
	UserID   uuid.UUID       `validate:"required"`
	Strategy string          `validate:"required"`
	Config   json.RawMessage `validate:"required"`
	Enabled  bool
}
